import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("Create a vendor", { tag: "@VEN-01" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const name = uniqueName("Acme Freight");

    // Act
    const res = await member.post("/api/vendors", {
      data: {
        name,
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(201);
    const vendor = await res.json();
    expect(vendor.name, JSON.stringify(vendor)).toBe(name);
    expect(vendor.category, JSON.stringify(vendor)).toBe("logistics");
    expect(vendor.contact_email, JSON.stringify(vendor)).toBe("ops@acmefreight.example");
    expect(vendor.status, JSON.stringify(vendor)).toBe("draft");

    await expect
      .poll(
        async () => {
          const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
          if (audit.status() !== 200) return `status ${audit.status()}`;
          const body = (await audit.json()) as { items: { action: string }[] };
          return body.items.map((item) => item.action);
        },
        { message: "vendor.created audit event recorded" },
      )
      .toContain("vendor.created");
  });
});
